import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n == 1:
        return 'C'

    # Compact counters over full history.
    opp_c = 0
    my_c = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for m, o in history:
        if m == 'C':
            my_c += 1
            if o == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if o == 'C':
                dc += 1
            else:
                dd += 1
        if o == 'C':
            opp_c += 1

    opp_d = n - opp_c
    my_d = n - my_c

    # Recent windows
    r10 = history[-10:] if n >= 10 else history
    r5 = history[-5:] if n >= 5 else history
    opp_d10 = sum(1 for m, o in r10 if o == 'D')
    opp_d5 = sum(1 for m, o in r5 if o == 'D')
    my_d5 = sum(1 for m, o in r5 if m == 'D')

    # Opponent streak
    streak = 1
    for i in range(n - 1, 0, -1):
        if history[i][1] == history[i - 1][1]:
            streak += 1
        else:
            break

    # End-game exploitation
    if n >= 96:
        if opp_c * 3 >= n * 2:
            return 'D'
        if opp_last == 'C':
            return 'D'
        return 'D'

    # Extremely cooperative opponent: stay cooperating, only rare late probe.
    if opp_d <= 1:
        if n >= 88 and opp_last == 'C':
            return 'D'
        return 'C'

    # Extremely defective opponent: retaliate hard.
    if opp_d >= n - 1 and n >= 6:
        if n < 95 and rng.randint(0, 5) == 0:
            return 'C'
        return 'D'

    # If recent opponent is almost all defections, defect.
    if opp_d10 >= 8:
        if n < 95 and opp_last == 'D' and rng.randint(0, 6) == 0:
            return 'C'
        return 'D'

    # Opponent recently mostly defected.
    if opp_d10 >= 5:
        if opp_last == 'C' and rng.randint(0, 4) == 0:
            return 'C'
        return 'D'

    # Long defection streak: retaliate but occasionally test cooperation.
    if opp_last == 'D' and streak >= 3:
        if streak < 8 and n < 92 and rng.randint(0, 3) == 0:
            return 'C'
        return 'D'

    # After being exploited when we cooperated last: punish briefly.
    if my_last == 'C' and opp_last == 'D':
        if opp_d10 >= 3:
            return 'D'
        if n < 93 and rng.randint(0, 3) == 0:
            return 'C'
        return 'D'

    # We defected and opponent cooperated: return to cooperation to rebuild.
    if my_last == 'D' and opp_last == 'C':
        if my_d > opp_d + 3 and n < 95 and rng.randint(0, 4) == 0:
            return 'D'
        return 'C'

    # Long cooperation streak: cooperate but rare probe (not too late).
    if opp_last == 'C' and streak >= 5:
        if n < 88 and rng.randint(0, 11) == 0:
            return 'D'
        return 'C'

    # Mixed regime: mostly tit-for-tat with slight forgiveness.
    if opp_last == 'C':
        return 'C'

    # Opponent defected: defect unless they've been fairly cooperative.
    coop_rate = opp_c / float(n)
    if coop_rate > 0.6 and rng.randint(0, 3) == 0:
        return 'C'
    if my_d5 <= 1 and rng.randint(0, 5) == 0:
        return 'C'
    return 'D'
